-- Objectif : corriger mojibake dans form_schema des dossiers preconfigures
-- Methode : JSON UTF-8 via UNHEX (fichier ASCII-safe)
SET NAMES utf8mb4;

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'ATT-SERV';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'AUD-CAB';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'AUTH-OCC';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'AUTH-TRAV';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'AVIS-TECH';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'DECL-CHANT';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'DECOMPTE';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'ENT-URG';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'INSP-CHANT';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'MISSION';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'RECLAM';

UPDATE preconfigured_dossiers SET form_schema = CONVERT(UNHEX('') USING utf8mb4), updated_at = NOW(6) WHERE code = 'RH-CONGE';

SELECT code,
  CASE WHEN HEX(form_schema) LIKE '%E2949C%' OR form_schema LIKE '%??%' THEN 'BAD' ELSE 'OK' END AS status,
  form_schema
FROM preconfigured_dossiers
ORDER BY code;
